import type { Trail } from '../types';

// Trail data will be generated by AI or fetched from API
export const trails: Trail[] = [];

// Helper function to get trail by ID
export function getTrailById(id: string): Trail | undefined {
    return trails.find(t => t.id === id);
}

// Helper function to filter trails by theme
export function filterTrailsByTheme(theme: string): Trail[] {
    return trails.filter(t => t.theme.includes(theme));
}

// Helper function to filter trails by time tags
export function filterTrailsByTime(time: string): Trail[] {
    return trails.filter(t => t.timeTags.includes(time as any));
}

// Helper function to get rain-friendly trails
export function getRainFriendlyTrails(): Trail[] {
    return trails.filter(t => t.theme === '雨天備案' || t.orderedPlaces.length <= 2);
}
